window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3bab1bf81a1e2715"]={"versions": [{"id": "FIG-3bab1bf81a1e2715", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Adaptive Platform, Spezifikation des E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Technischer Zweck:</strong> Normative Definition des atomaren Einzelschritts „Read Length“ innerhalb der generischen Prüfroutinen <code>E2E_PXXmSourceCheck()</code> und <code>E2E_PXXmSinkCheck()</code>. Diese Funktionen dienen der E2E-Header-Validierung von geschützten Client-Server-Methodenaufrufen bzw. -Antworten (Method Profiles <code>PXXm</code>, z. B. P04m, P07m, P22m für SOME/IP-RPCs) zur Deserialisierung der übertragenen Nutzdatenlänge aus dem Bytestrom vor der nachgelagerten Integritäts- und Plausibilitätsprüfung.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aufrufende Aktivitäten / Scope:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Prüffunktion an der Quelle/Client-Rückmeldung bzw. Server-Abfrage.\n</li><li><code>E2E_PXXmSinkCheck()</code>: Prüffunktion an der Senke/Server-Anfrage bzw. Client-Antwort.\n</li><li>Das Symbol <code>∞</code> deklariert die wiederverwendbare Unteraktivität; <code>&quot;XX&quot;</code> dient als Platzhalter (Wildcard) für das jeweils instanziierte Methodenprofil.\n</li></ul>\n</li><li><strong>Eingangsdaten &amp; Puffer:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingehender Bytestring (Rohdaten-Array <code>uint8*</code>) der empfangenen PDU/Nachricht.\n</li></ul>\n</li><li><strong>Ausgangsdaten / Lokale Variablen:</strong>\n<ul class=\"fig-list\"><li><code>ReceivedLength</code>: Lokale skalare Ganzzahlvariable (je nach Profil <code>uint16</code> oder <code>uint32</code>), die den extrahierten Längenwert aufnimmt.\n</li></ul>\n</li><li><strong>Profil-Konfigurationsparameter (Placeholders):</strong>\n<ul class=\"fig-list\"><li><code>Offset</code>: Basis-Offset (in Bytes) des E2E-Headers innerhalb des Datenpuffers <code>Data</code>.\n</li><li><code>PXXMLENGTH_POS</code>: Profilspezifische relative Byte-Startposition des Längenfeldes innerhalb des E2E-Headers.\n</li><li><code>PXXMLENGTH_LEN</code>: Statische Länge des Längenfeldes in Bytes (z. B. 2 oder 4 Bytes).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Kontrollfluss startet am Initial Node unmittelbar vor dem Schritt „Read Length“.\n</li><li><strong>Byte-Extraktion:</strong>\n<ul class=\"fig-list\"><li>Zugriff auf den Sub-Bereich des Datenstroms <code>Data</code>:\n $Startindex = Offset + PXXMLENGTH_POS$\n $$\\text{Endindex} = \\text{Offset} + \\text{PXXMLENGTH\\_POS} + \\text{PXXMLENGTH\\_LEN} - 1$$\n</li></ul>\n</li><li><strong>Byte-Order-Transformation (Big-Endian):</strong>\n<ul class=\"fig-list\"><li>Die sequentiell gelesenen Bytes werden in Network Byte Order (Most Significant Byte zuerst) interpretiert und in die Host-Variable <code>ReceivedLength</code> konvertiert (MSB an höchster Bitposition, LSB an niedrigster Bitposition).\n</li></ul>\n</li><li><strong>Terminierung:</strong> Nach erfolgreicher Zuweisung endet der Kontrollfluss am Activity Final Node; es existieren innerhalb dieses atomaren Schritts keine bedingten Verzweigungen, Schleifen oder asynchronen Callbacks.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Feste Endianness-Vorschrift:</strong> Die Längenkodierung im E2E-Header ist zwingend Big-Endian. Auf typischen Little-Endian-Zielarchitekturen (ARM Cortex-M/R/A, x86/x64) muss der Stack-Entwickler eine explizite Byte-Drehung implementieren (z. B. über Hardware-Builtins wie <code>__builtin_bswap16</code> / <code>__builtin_bswap32</code> bzw. <code>rbit</code>/<code>rev</code>).\n</li><li><strong>Defensiver Zugriff &amp; Bounds-Checking:</strong> Vor Eintritt in diesen Schritt muss im umgebenden Check-Ablauf sichergestellt sein, dass die tatsächliche Länge des Puffers <code>Data</code> mindestens $\\text{Offset} + \\text{PXXMLENGTH\\_POS} + \\text{PXXMLENGTH\\_LEN}$ beträgt. Andernfalls droht ein Pufferüberlauf (Out-of-Bounds Read), der nach AUTOSAR E2E-Regelwerk mit <code>E2E_E_INPUTERR_WRONG</code> abzufangen ist.\n</li><li><strong>Generische Profil-Abstraktion:</strong> Die Werte <code>PXXMLENGTH_POS</code> und <code>PXXMLENGTH_LEN</code> sind nicht fest codiert, sondern aus den profilabhängigen Spezifikationstabellen bzw. den generierten Konfigurationsstrukturen (<code>E2E_PXXmConfigType</code>) abzuleiten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd51af79bb17c4d1", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Adaptive Platform, Spezifikation des E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>).\n</li><li><strong>Technischer Zweck:</strong> Normative Definition des atomaren Einzelschritts „Read Length“ innerhalb der generischen Prüfroutinen <code>E2E_PXXmSourceCheck()</code> und <code>E2E_PXXmSinkCheck()</code>. Diese Funktionen dienen der E2E-Header-Validierung von geschützten Client-Server-Methodenaufrufen bzw. -Antworten (Method Profiles <code>PXXm</code>, z. B. P04m, P07m, P22m für SOME/IP-RPCs) zur Deserialisierung der übertragenen Nutzdatenlänge aus dem Bytestrom vor der nachgelagerten Integritäts- und Plausibilitätsprüfung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aufrufende Aktivitäten / Scope:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Prüffunktion an der Quelle/Client-Rückmeldung bzw. Server-Abfrage.\n</li><li><code>E2E_PXXmSinkCheck()</code>: Prüffunktion an der Senke/Server-Anfrage bzw. Client-Antwort.\n</li><li>Das Symbol <code>∞</code> deklariert die wiederverwendbare Unteraktivität; <code>&quot;XX&quot;</code> dient als Platzhalter (Wildcard) für das jeweils instanziierte Methodenprofil.\n</li></ul>\n</li><li><strong>Eingangsdaten &amp; Puffer:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingehender Bytestring (Rohdaten-Array <code>uint8*</code>) der empfangenen PDU/Nachricht.\n</li></ul>\n</li><li><strong>Ausgangsdaten / Lokale Variablen:</strong>\n<ul class=\"fig-list\"><li><code>ReceivedLength</code>: Lokale skalare Ganzzahlvariable (je nach Profil <code>uint16</code> oder <code>uint32</code>), die den extrahierten Längenwert aufnimmt.\n</li></ul>\n</li><li><strong>Profil-Konfigurationsparameter (Placeholders):</strong>\n<ul class=\"fig-list\"><li><code>Offset</code>: Basis-Offset (in Bytes) des E2E-Headers innerhalb des Datenpuffers <code>Data</code>.\n</li><li><code>PXXMLENGTH_POS</code>: Profilspezifische relative Byte-Startposition des Längenfeldes innerhalb des E2E-Headers.\n</li><li><code>PXXMLENGTH_LEN</code>: Statische Länge des Längenfeldes in Bytes (z. B. 2 oder 4 Bytes).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Kontrollfluss startet am Initial Node unmittelbar vor dem Schritt „Read Length“.\n</li><li><strong>Byte-Extraktion:</strong>\n<ul class=\"fig-list\"><li>Zugriff auf den Sub-Bereich des Datenstroms <code>Data</code>:\n $Startindex = Offset + PXXMLENGTH_POS$\n $$\\text{Endindex} = \\text{Offset} + \\text{PXXMLENGTH\\_POS} + \\text{PXXMLENGTH\\_LEN} - 1$$\n</li></ul>\n</li><li><strong>Byte-Order-Transformation (Big-Endian):</strong>\n<ul class=\"fig-list\"><li>Die sequentiell gelesenen Bytes werden in Network Byte Order (Most Significant Byte zuerst) interpretiert und in die Host-Variable <code>ReceivedLength</code> konvertiert (MSB an höchster Bitposition, LSB an niedrigster Bitposition).\n</li></ul>\n</li><li><strong>Terminierung:</strong> Nach erfolgreicher Zuweisung endet der Kontrollfluss am Activity Final Node; es existieren innerhalb dieses atomaren Schritts keine bedingten Verzweigungen, Schleifen oder asynchronen Callbacks.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Feste Endianness-Vorschrift:</strong> Die Längenkodierung im E2E-Header ist zwingend Big-Endian. Auf typischen Little-Endian-Zielarchitekturen (ARM Cortex-M/R/A, x86/x64) muss der Stack-Entwickler eine explizite Byte-Drehung implementieren (z. B. über Hardware-Builtins wie <code>__builtin_bswap16</code> / <code>__builtin_bswap32</code> bzw. <code>rbit</code>/<code>rev</code>).\n</li><li><strong>Defensiver Zugriff &amp; Bounds-Checking:</strong> Vor Eintritt in diesen Schritt muss im umgebenden Check-Ablauf sichergestellt sein, dass die tatsächliche Länge des Puffers <code>Data</code> mindestens $\\text{Offset} + \\text{PXXMLENGTH\\_POS} + \\text{PXXMLENGTH\\_LEN}$ beträgt. Andernfalls droht ein Pufferüberlauf (Out-of-Bounds Read), der nach AUTOSAR E2E-Regelwerk mit <code>E2E_E_INPUTERR_WRONG</code> abzufangen ist.\n</li><li><strong>Generische Profil-Abstraktion:</strong> Die Werte <code>PXXMLENGTH_POS</code> und <code>PXXMLENGTH_LEN</code> sind nicht fest codiert, sondern aus den profilabhängigen Spezifikationstabellen bzw. den generierten Konfigurationsstrukturen (<code>E2E_PXXmConfigType</code>) abzuleiten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3bab1bf81a1e2715", "to": "FIG-cd51af79bb17c4d1", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bereinigung des Diagrammkopfs: Am oberen Bildrand abgeschnittener Spezifikationstext aus dem Dokumenten-Header bzw. der Vorabschnittszeile entfernt.\n</li></ul>"}]};
